    scenarios: { summit: { name: 'Дипломатичний саміт', lore: 'Посол, Голова ради, Нотаріус і Лобіст за одним столом: кожна нічия і кожен імунітет — політика.' }, bought_votes: { name: 'Куплені голоси', lore: 'Скарбник і Шантажист проти Прокурора й Нотаріуса. Гравець робить ставки. Рахуйте руки двічі.' }, quiet_revolution: { name: 'Тиха революція', lore: 'Провокатор виставляє, Пастор ховає, Ляльковод водить чужі голоси, Миротворець скасовує страти. Суддя і Мер — остання опора міста.' }, big_politics: { name: 'Велика політика', lore: 'Усі дванадцять дипломатичних карт плюс Мер, Суддя, Пʼяниця й Альтруїст. Кожне голосування — вистава.' } }
