    abilities: { negvote: 'blackmail', provoke: 'provocation', stuff: 'bribe', certify: 'certification', sanctuary: 'sanctuary', bet: 'bet', shield: 'expulsion shield', puppet: 'puppet', prosecute: 'accusation' },
