    scenarios: { summit: { name: 'Diplomatic Summit', lore: 'Ambassador, Chairman, Notary and Lobbyist at one table: every tie and every immunity is politics.' }, bought_votes: { name: 'Bought Votes', lore: 'Treasurer and Blackmailer against Prosecutor and Notary. The Gambler places bets. Count the hands twice.' }, quiet_revolution: { name: 'Quiet Revolution', lore: 'The Provocateur nominates, the Pastor hides, the Puppeteer steers votes, the Peacemaker cancels executions. The Judge and the Mayor are the town\'s last hope.' }, big_politics: { name: 'Big Politics', lore: 'All twelve diplomatic cards plus the Mayor, Judge, Drunk and Altruist. Every vote is a show.' } }
